        this.filterSTEP = [];            // 빈 배열 = 전체 (필터 없음)
        this._unfilteredGridImages = null;  // 필터 변경 시 재필터링용 원본 그리드 이미지

        // 개인색 설정 상태 (기본값: false)
        this.personalizedColorEnabled = true; // 🔥 기본값: 개인색 설정 활성화

