    /**
     * Composite Grid로 전환 (8개 히트맵 표시)
     */
    async switchToCompositeGrid(result) {
        // 🔥 Composite 완료 → composite_map/{LoginId} 폴더를 일반 그리드로 표시
        const outputDir = result?.output_dir;
        if (!outputDir) {
            alert('생성된 히트맵이 없습니다.');
            return;
        }
        this._closeCompositeMeasureFloatingPanels();

        this._personalizedColorCacheBuster = Date.now();
        this.selectedGrades.clear();
        this.isCompositeMode = true;

        const sourceImages = result.source_image_paths || this.lastCompositeSourceImages || [];
        this.compositeSession = {
            sourceImageCount: result.image_count || result.source_images,
            outputDir,
            sourceImagePaths: sourceImages,
            imageSize: result.image_size,
            processingTime: result.processing_time,
            numba: result.numba || null,
            generatedAt: result.generated_at,
            selectionMode: result.selection_mode || this.lastCompositeSelection?.mode || null,
            selectedChipCount: result.selected_chip_count || this.lastCompositeSelection?.chipCoords?.length || 0,
            selectedShotCount: result.selected_shot_count || this.lastCompositeSelection?.shotGroups?.length || 0,
            selectedSourceChipCount: result.selected_source_chip_count || null,
            selectedMissingChipCount: result.selected_missing_chip_count || 0,
            shotShape: result.selected_shot_shape || null,
            compositeSampleCount: result.composite_sample_count || null,
            selectionCrop: result.selection_crop || null,
            shotLocalSquareWeighted: result.shot_local_square_weighted === true ||
                this.lastCompositeSelection?.shotLocalSquareWeighted === true,
            sumMaps: [],
        };
        this.lastCompositeSourceImages = sourceImages;

        // 🔥 Composite 결과 폴더 로드 전 필터/선택 상태 초기화
        this.filterLT = [];
        this.filterTM = [];
        this.filterSTEP = [];
        this.gridSelectedIdxs = [];
        this.gridSelectedSet = new Set();
        this.selectedFolders = new Set();
        this.overlayMode = null;
        this._ratioActiveItemKey = null;
        this._measureCheckedItems = [];
        this._gridMeasureMap = null;

        // 🔥 핵심: composite_map/{LoginId} 폴더를 일반 폴더처럼 로드
        await this.loadImagesInFolderAndShowGrid(outputDir);
        if (typeof this.hideLotListModal === 'function') this.hideLotListModal();
        this.clearGridSelectionMarks({ hidePanel: true });
        this.updateContextMenuState();
    }

